	DELVELOG_TOTAL_TIME = "Tiempo total:",
	INFO_DRAWER_BODY_DELVELOG = "El Registro de cavernas anota cada caverna de Medianoche que completas con este personaje. Haz clic en una caverna para desplegar sus últimas partidas. Cada una muestra nivel, tiempo, muertes, si usaste una Llave de cofre restaurada y el jefe final. El registro funciona en segundo plano; no necesitas tener esta pestaña abierta.",
	TAB_WORLD = "Void & Rituals",
	TAB_EVENTS = "Eventos",
	EVENTS_SUBTITLE = "Todos los eventos de mundo de Midnight: lo que ocurre ahora y lo que viene en las próximas 24 horas. Haz clic en un evento activo para trazar una ruta; pasa el ratón para ver qué es y qué recompensa.",
	EVENTS_NONE = "Ahora mismo no hay eventos de mundo visibles — puede que el planificador aún esté cargando. Inténtalo de nuevo en unos segundos.",
	WORLD_EVENTS_HEADER = "Eventos de mundo",
