	EVENT_INFO_REWARD_LABEL = "Recompensas:",
	EVENT_INFO_CLICK_HINT = "Haz clic para trazar una ruta.",
	EVENT_INFO_STORMARION_DESC = "Defensa de torre en Voidstorm en la Stormarion Citadel — empieza cada 30 minutos. Repele las oleadas junto con todos los de la zona.",
	EVENT_INFO_STORMARION_REWARD = "Por intento: Stormarion Core, Voidlight Marl, oro y equipo veterano. El alijo semanal 'Stand Your Ground' tiene posibilidad de dar la montura Contained Stormarion Defender y una mascota, además de reputación con The Singularity.",
	EVENT_INFO_HARANIR_DESC = "Un evento de historia más tranquilo en Harandar. Coge la misión semanal 'Lost Legends', elige una reliquia y juega su cadena de misiones (apto para jugar en solitario).",
	EVENT_INFO_HARANIR_REWARD = "Un alijo semanal, reputación Hara'ti y un objeto de decoración ligado a tu reliquia. Reúne todas las historias de reliquias para el título 'Chronicler of the Haranir'.",
	EVENT_WEEKLY_DONE = "semanal hecha",
	EVENT_WEEKLY_TURNIN = "semanal: ¡entregar!",
	EVENT_WEEKLY_ACTIVE = "semanal: en curso",
	EVENT_WEEKLY_TODO = "semanal disponible",
	EVENT_WEEKLY_LABEL = "Semanal:",
	MODEL_PREVIEW_HINT = "Arrastra para girar · rueda para zoom",
	MODEL_PREVIEW_SPIN = "Girar",
	MODEL_PREVIEW_RESET = "Reiniciar",
	MODEL_PREVIEW_REWARDS_HINT = "Mayús+clic: ver recompensas",
	WORLD_SUBTITLE = "Contenido de mundo semanal de Midnight en Quel'Thalas. Un Sitio ritual está activo en una zona y el Vacío asalta otra — ambos comparten el centro del Bazar, los Reconocimientos de campo y el renombre.",
	INFO_DRAWER_BODY_WORLD = "Void & Rituals reúne los dos sistemas de mundo rotativos de Midnight. Sitios rituales: altera el sitio activo (icono morado) en su obelisco. Asaltos del Vacío: limpia Golpes del Vacío en la zona activa para activar una Incursión del Vacío. Ambos dan Reconocimientos de campo, llenan tu fila de mundo de la Gran Cámara y alimentan el renombre común de Sitios rituales. Ambas semanales se cogen en el centro del Bazar en Lunargenta.",
	TAB_REFERENCE = "Básicos",
	REF_PANEL_INTRO = "Explicaciones sencillas de sistemas de endgame. Aquí habrá más temas con el tiempo.",
	REF_MORE_COMING = "Próximamente más guías (profesiones, equipo, etc.).",
	INFO_DRAWER_BODY_REFERENCE = "Guías para principiantes: Crests, dónde gastarlos y bonos de banda guerrera. Llegarán más temas (profesiones, etc.).",
	TAB_SMC = "Silvermoon City",
	TAB_PROFESSIONS = "Profesiones",
	TAB_GUIDE = "Guías de nivelación",
	TAB_MACROS = "macros",
	TAB_CONSUMABLES = "Consumibles",
	TAB_ACADEMY = "Academia de roles",
	TAB_TOOLBOX = "Herramientas",
	-- Artículos del códice del parche 12.0.7
	CODEX_127_SHOWDOWNS_TITLE = "Showdowns: Naigtal y Val (12.0.7)",
	CODEX_127_SHOWDOWNS_BODY = "Un portal en el Voidstorm (Screaming Ridge) lleva a uno de dos mundos del Vacío en rotación: el fúngico Naigtal o el gélido Val. Ambos ofrecen misiones de mundo, raros, eventos de zona y un jefe de mundo (Nexus-Captain Leth'ir / Imperator Pertinax). La semanal de Showdown otorga una Riftstalker's Cache y cuenta para la fila World de la Gran Cámara. La Heroic World Tier opcional sube dificultad y recompensas — se elige en el portal. Comienza con Riftblade Maella en Lunargenta.",
	CODEX_127_SPOREFALL_TITLE = "Banda Sporefall (12.0.7)",
	CODEX_127_SPOREFALL_BODY = "Banda de un solo jefe en Harandar: Rotmire, un gigante fúngico. Mismo nivel de la Temporada 1 con mayor nivel de objeto (LFR 259 / Normal 272 / Heroico 285 / Mítico 298); el Mítico es flexible de 15 a 25 jugadores. Recoge un Delicious Sporesnack una vez por semana en cualquier dificultad — cuatro en total compran la montura Luminous Sporeglider.",
	CODEX_127_FOLIO_TITLE = "Omnium Folio y Runas (12.0.7)",
	CODEX_127_FOLIO_BODY = "Nuevo sistema de poder que no ocupa hueco de equipo. Se desbloquea con la cadena del Sunstrider Omnium junto a Umbric y Rommath en Quel'Danas. Cada semana, la misión 'Seeking Knowledge' da un Mote of Omnial Inquiry para abrir una de las cinco filas de runas; las runas se cambian gratis fuera de combate.",
	CODEX_127_TIMEWAYS_TITLE = "Turbulent Timeways V (30 jun - 11 ago)",
	CODEX_127_TIMEWAYS_BODY = "Maratón de Paseo temporal con seis mazmorras de Dragonflight. Haz cuatro mazmorras en una semana para el buff Mastery de esa semana; consigue Mastery en cuatro semanas distintas para la montura Spawn of Vyranoth.",
	CODEX_127_RITUALRENOWN_TITLE = "Renombre de Sitios rituales (12.0.7)",
	CODEX_127_RITUALRENOWN_BODY = "Los Sitios rituales tienen una vía de Renombre por cuenta (8 rangos) en la ventana Journeys. Subir de rango enriquece cada sitio: Regeneration Orbs que curan, luego enemigos raros (rango 4), santuarios de mejora (rango 5), tesoros mayores (rango 7) y élites raros (rango 8) — todos con botín extra. También desbloquea artículos de vendedores en Lunargenta: decoración de hogar del Vacío (rango 3, Rae'ana), mascotas (rango 6, Sergeant Vornin) y la montura Void-Touched Hawkstrider (rango 8, Sergeant Vornin). Cada recompensa es de banda de guerra (Warband), así que tu progreso cuenta para toda la cuenta. Haz clic en los Loa Shrines luminosos dentro de un sitio para un buff de estadística de 60 minutos (p. ej. +10% de golpe crítico).",
	TAB_BETA_BADGE = "Beta",
	TAB_BETA_TOOLTIP_TITLE = "En desarrollo",
	TAB_BETA_TOOLTIP_BODY = "Esta pestaña está en beta temprana — el contenido está incompleto, puede cambiar a menudo y aún no está listo para uso completo.",
	TAB_ADDONS = "Complementos",
	SEARCH_CHAT_TAB_ACADEMY = "Pestaña abierta: Academia de roles",
	ACADEMY_SUBTITLE = "Clase magistral breve para tanquear y curar en grupos: mentalidad, casillas de preparación y una suave rampa hacia las mazmorras. No es una guía de análisis.",
	ACADEMY_TRACK_TANK = "pista de tanques",
	ACADEMY_TRACK_HEAL = "Curar pista",
	ACADEMY_LINK_MACROS = "macros",
	ACADEMY_LINK_CONSUMABLES = "Consumibles",
	ACADEMY_LINK_GUIDE = "Guías",
	ACADEMY_LINK_DELVES = "profundidades",
	ACADEMY_LINK_CLASS = "mi clase",
	ACADEMY_CLASS_FMT = "Iniciado sesión: %s - %s (abre Macros / Consumibles / Guías desde la barra lateral)",
	ACADEMY_CLASS_OPEN_CHAT_FMT = "Macros abiertas para %s - %s. Consulte también Consumibles para matraces y recipientes.",
	ACADEMY_PREF_TITLE = "Lista de verificación previa al vuelo (marque cuando esté listo)",
	ACADEMY_PREF_HINT = "Las garrapatas se guardan en su configuración. Abra la pestaña correspondiente de la barra lateral cuando esté preparado.",
	ACADEMY_PREF_TANK_INTERRUPT = "Interrumpir macro en mi barra (pestaña Macros)",
	ACADEMY_PREF_TANK_DEFENSIVE = "Un listo para la defensiva (Guías -> pestaña Defensivas o En grupos)",
	ACADEMY_PREF_TANK_CONSUMABLES = "Matraz/olla lista (pestaña Consumibles)",
	ACADEMY_PREF_TANK_TAUNT = "Conozco mi clave de burla (prueba simulada una vez)",
	ACADEMY_PREF_HEAL_MACROS = "Pasar el ratón por encima/enfocar macros de curación (pestaña Macros)",
	ACADEMY_PREF_HEAL_DEFENSIVE = "Defensa personal en barra (Guías -> Defensivas o En grupos)",
	ACADEMY_PREF_HEAL_CONSUMABLES = "Olla de maná/frasco (pestaña Consumibles)",
	ACADEMY_PREF_HEAL_PRACTICE = "Practiqué la curación flotante con un amigo una vez.",
	ACADEMY_TANK_INTRO_TITLE = "Mentalidad de tanque",
	ACADEMY_TANK_INTRO_BODY = "Tu trabajo es marcar el ritmo y mantener la atención, no superar los medidores de daño.\\n\\nUn tirón constante es mejor que una rotación perfecta en un grupo muerto. Diga en voz alta si le ayuda: \\\"tirando hacia adentro 3\\\".",
	ACADEMY_TANK_PULL_TITLE = "Durante un tirón (primeros 10 segundos)",
	ACADEMY_TANK_PULL_BODY = "1. Coge el paquete (burla/amenaza).\\n2. Enfréntate a los enemigos lejos del grupo cuando puedas.\\n3. Utilice uno defensivo si el daño aumenta; guarde el segundo para \\\"oh no\\\".\\n4. Interrumpe el lanzamiento que más duele (a menudo, curación o gran golpe).\\n\\nNo necesitas todas las habilidades en tiempo de reutilización de inmediato.",
	ACADEMY_TANK_WIPE_TITLE = "cuando sale mal",
	ACADEMY_TANK_WIPE_BODY = "Un borrado son datos, no un veredicto. Pregunte: \\\"¿Estaba demasiado adelantado?\\\" o \\\"¿Salvé una defensiva?\\\"\\n\\nRepara, come, vuelve a intentarlo.",
	ACADEMY_TANK_DUNGEON_TITLE = "Tu primera mazmorra (normal)",
	ACADEMY_TANK_DUNGEON_BODY = "Empieza normalmente con amigos o gremios si puedes. Ve despacio al tirar: dos paquetes pequeños vencen a una cadena enorme.\\n\\nObserva el maná del sanador; pausa entre tirones. Está bien solicitar CC o \"aún no hay gran atracción\".",
	ACADEMY_TANK_RAID_TITLE = "Incursiones y LFR (más tarde)",
	ACADEMY_TANK_RAID_BODY = "LFR es la suave introducción de la incursión: perdonadores, muchos sanadores. Concéntrate en los tiempos de las burlas de los jefes y en quedarte quieto en el lugar correcto.\\n\\nEl tanque de incursión mítica no es el siguiente paso: primero la comodidad en heroico/LFR.",
	ACADEMY_TANK_CHAT_TITLE = "charla de fiesta",
	ACADEMY_CHAT_HINT = "Haga clic en una línea o en el icono de copiar, luego Ctrl+C para pegar en el chat del grupo.",
	ACADEMY_CHAT_COPY_TIP = "Seleccione esta línea (Ctrl+C)",
	ACADEMY_TANK_CHAT_BODY = "\\\"Aún estoy aprendiendo tanque - ve despacio por favor.\\\"\\n\\\"Atrayendo 3...\\\"\\n\\\"Necesito un respiro para maná.\\\"\\n\\\"Interrumpe en [nombre del hechizo] - Lo tengo a continuación.\\\"\\n\\\"Un intento más - ahora sé que tira.\\\"",
	ACADEMY_TANK_LADDER_TITLE = "Escalera de ansiedad (orden recomendado)",
	ACADEMY_TANK_LADDER_BODY = "1. Élites del mundo abierto con un amigo\\n2. Profundidades (instancia más pequeña - pestaña Profundidades)\\n3. Mazmorra normal con gente en la que confías\\n4. Heroico/LFR cuando te sientas cómodo\\n\\nSalta un paso hasta que te parezca aburrido, no aterrador.",
	ACADEMY_TANK_BOTH_TITLE = "¿Aprender a sanar también?",
	ACADEMY_TANK_BOTH_BODY = "Genial, pero elige un papel principal en las mazmorras por un tiempo. Practica el otro en excavaciones o en un mundo abierto.\\n\\nCambiar de tanque y curarte en el mismo pug M+ duplica el estrés; el dominio de un rol primero genera confianza para el segundo.",
	ACADEMY_HEAL_INTRO_TITLE = "sanar la mentalidad",
	ACADEMY_HEAL_INTRO_BODY = "No eres responsable de que todos tengan un 100% de salud todo el tiempo.\\n\\nTu trabajo es clasificar: mantener vivo el tanque, salvar a la persona que está a punto de morir y luego el resto. Algo de daño es normal: la curación excesiva por pánico agota el maná.",
	ACADEMY_HEAL_TRIAGE_TITLE = "Triaje (¿quién primero?)",
	ACADEMY_HEAL_TRIAGE_BODY = "1. Tú (si estás muriendo, el sanador muerto no cura a nadie)\\n2. Tanque (si el paquete todavía está en ellos)\\n3. Cualquier persona con menos de ~40 % o con una desventaja mortal\\n4. Todos los demás con curas eficientes\\n\\nGran curación después de un gran daño; pequeñas curas entre eventos.",
	ACADEMY_HEAL_WIPE_TITLE = "cuando sale mal",
	ACADEMY_HEAL_WIPE_BODY = "\"¿Podría haber salvado el tanque?\" es la pregunta útil, no \"¿por qué el DPS se quedó en llamas?\"\\n\\nSi el maná estaba vacío, usa hechizos más eficientes la próxima vez. Una toallita no significa que no puedas sanar.",
	ACADEMY_HEAL_DUNGEON_TITLE = "Tu primera mazmorra (normal)",
	ACADEMY_HEAL_DUNGEON_BODY = "Dígale al grupo que está aprendiendo. Párese dentro del alcance del tanque; deja que el DPS rasque antes de gastar maná.\\n\\nEntre tiradas: bebe, mejora, respira. Se le permite decir \\\"oom, 5 segundos\\\".",
	ACADEMY_HEAL_RAID_TITLE = "Incursiones y LFR (más tarde)",
	ACADEMY_HEAL_RAID_BODY = "LFR: el daño en toda la banda es predecible después de una limpieza. Aprende el cronómetro de pelea, no las barras de cada jugador.\\n\\nLas curas de incursión usan la misma clasificación: primero las ventanas de enfriamiento del tanque y de la incursión.",
	ACADEMY_HEAL_CHAT_TITLE = "charla de fiesta",
	ACADEMY_HEAL_CHAT_BODY = "\\\"Aprendiendo sanador - llamaré maná bajo.\\\"\\n\\\"El tanque es prioridad - grita si necesitas un respiro.\\\"\\n\\\"Gran curación para ti - cuida tu salud.\\\"\\n\\\"Oom 5 segundos entre tirones.\\\"\\n\\\"Eso fue por mi culpa - guardaré más para el tanque el próximo tirón.\\\"",
	ACADEMY_HEAL_LADDER_TITLE = "Escalera de ansiedad (orden recomendado)",
	ACADEMY_HEAL_LADDER_BODY = "1. Cura a un amigo en mundo abierto\\n2. Profundidades con un grupo pequeño\\n3. Mazmorra normal con amigos pacientes\\n4. Incursión LFR/heroica cuando esté lista\\n\\nLas profundidades son el paso más suave hacia el contenido instanciado.",
	ACADEMY_HEAL_BOTH_TITLE = "¿Tanque de aprendizaje también?",
	ACADEMY_HEAL_BOTH_BODY = "Utilice la ruta de tanques para hacer cola en las mazmorras; sigue curándote en excavaciones hasta que tanquear te resulte familiar.\\n\\nDos roles en una semana en pugs es mucho; un rol como \\\"principal\\\" reduce el miedo.",
	INFO_DRAWER_BODY_ACADEMY = "Academia de roles: pistas de tanque/curación, casillas de verificación previas al vuelo, notas de mazmorra versus incursión y líneas de chat del grupo. Guías de nivelación agrega una pestaña de asesor en grupos por rol. Utilice la barra lateral para macros, consumibles, guías y profundidades.",
	TAB_GUIDE_SUB_GUIDE = "Guía",
	TAB_GUIDE_SUB_LAYOUT = "Disposición",
	TAB_LEVELING_SUB_LAYOUT = "Disposición",
	MACROS_TYPE_INTERRUPT = "Interrumpir",
	MACROS_TYPE_UTILITY = "Utilidad",
	MACROS_CONSUMABLES_SUBTITLE = "Las mejores selecciones de la temporada 1 de medianoche (frasco, ollas, banquete, comida). Pase el cursor sobre una fila para ver la información sobre herramientas del elemento.",
	MACROS_CONS_NO_DATA = "Aún no hay datos de consumibles para esta clase y especificación.",
