	CONS_COPY_TT = "Clic: copiar nombre (para la casa de subastas)",
	DELVE_SHARE_XLOC_HEADER_FMT = "%s compartió consejos de sima — aquí en tu idioma:",
	PROFHUB_WEEKLY_HEADER = "Esta semana",
	PROFHUB_WEEKLY_TRAINER = "mision semanal del instructor",
	PROFHUB_WEEKLY_ESSENCES = "Mats de desencantamiento en las bolsas",
	PROFHUB_GOAL_LABEL = "Objetivo del consejo:",
	PROFHUB_GOAL_ALLROUND = "Versátil",
	PROFHUB_GOAL_GOLD = "Oro",
	PROFHUB_GOAL_SELF = "Autosuficiente",
	PROFHUB_GOAL_TT_ALLROUND = "La ruta inicial de consenso: un orden equilibrado para tus primeros puntos — buena capacidad de fabricación sin atarte a un nicho.",
	PROFHUB_GOAL_TT_GOLD = "Prioriza árboles cuyos productos se venden bien (encantamientos, frascos, cooldowns de fardos, gemas talladas). Elige esto si tu meta es el oro.",
	PROFHUB_GOAL_TT_SELF = "Prioriza fabricar tus propios consumibles y equipo, y la autosuficiencia de materiales, por encima del valor de mercado.",
	PROFHUB_WEEKLY_TRAINER_REQ_ENCH = "(se desbloquea con la intro del capitán Flaresworn — estación de encargos; además requiere habilidad 25)",
	PROFHUB_ACCESSORY_HINT_FMT = "Consejo: %d hueco(s) de accesorio vacío(s) — los accesorios dan habilidad y stats. Otros artesanos los fabrican (subasta: Equipo de profesión).",
	INFO_DRAWER_BODY_CONSUMABLES = "Consumibles de la temporada 1 de Midnight por especificación (lista Wowhead). Utilice Mi personaje, < > o busque (por ejemplo, estragos, bestia) para obtener una vista previa de otra especificación sin volver a iniciar sesión.",
	MACROS_MACRO_NAME_FMT = "%s",
	MACROS_COPY_SUFFIX = "Copie el texto a continuación en Esc > Macros > Nuevo. Luego arrastre el ícono de macro a un lugar en su barra de acciones (por ejemplo 1, 2 o E).",
	MACROS_INTERRUPT_SUBTITLE = "Consejo de medianoche: detiene un lanzamiento enemigo con una sola pulsación. Elige una variante arriba (Foco o Mouseover), lee la nota y copia el texto a continuación.",
	MACROS_INTERRUPT_VARIANT_FOCUS = "Foco",
	MACROS_INTERRUPT_VARIANT_MOUSEOVER = "Mouseover",
	MACROS_INTERRUPT_DESC_FOCUS = "Interrumpe tu foco si es un enemigo vivo; si no, tu objetivo actual. Pon al lanzador peligroso como foco una vez (/focus) y sigue golpeando tu propio objetivo — esta macro nunca cambia ni borra tu foco.",
	MACROS_INTERRUPT_DESC_MOUSEOVER = "Interrumpe al enemigo bajo tu cursor (también funciona sobre placas de nombre y marcos); si no, tu objetivo actual. Sin foco: apunta al lanzador y pulsa.",
	MACROS_UTILITY_SUBTITLE = "Consejo de medianoche: macros útiles para su especificación (cursor, mouseover, enfoque). Elija uno de arriba, lea la nota y luego copie el texto a continuación.",
	MACROS_ERR_NO_UTILITY = "Aún no se enumeran macros de utilidades para esta especificación.",
	MACROS_PANEL_SUBTITLE = "Consejo de medianoche: detiene el lanzamiento de un enemigo con solo presionar un botón.\\n\\nEnfócate primero: enfoca el lanzador que necesitas patear y luego presiona. ¿Sin enfoque? La macro elige un enemigo cercano, interrumpe y te devuelve al enemigo contra el que estabas luchando. No comprueba todos los mobs que te rodean.\\n\\nCopie el texto siguiente en Esc > Macros > Nuevo. Luego arrastre el ícono de macro a un lugar en su barra de acciones (por ejemplo 1, 2 o E).",
	MACROS_ERR_NO_TYPE = "Este tipo de macro aún no está disponible.",
	MACROS_SPEC_LINE_FMT = "%s - %s",
	MACROS_COPY_BUTTON = "Seleccionar todo",
	MACROS_COPY_HINT = "Ctrl+C para copiar y luego pegar en la ventana de macro.",
	MACROS_ERR_NO_SPEC = "Elija una especialización (nivel 10+) para ver su macro de interrupción.",
	MACROS_ERR_EMPTY_SPEC = "No se incluye ninguna macro de interrupción para esta especialización (por ejemplo, Disco/Holy Priest). Utilice su kit de herramientas de clase según sea necesario.",
	MACROS_ERR_NO_DATA = "Aún no hay ninguna entrada de macro de interrupción para esta clase en Midnight Helper.",
	MACROS_ERR_GENERIC = "No se pudo cargar una macro de interrupción para este personaje.",
	KEYBIND_HUNTER_CAT_MAIN_ROTATION = "Rotación principal",
	KEYBIND_HUNTER_CAT_SPENDER = "Gastador",
	KEYBIND_HUNTER_CAT_UTILITY = "Utilidad",
