	KEYBIND_ROLE_INTERRUPT = "Interrumpir",
	KEYBIND_ROLE_MAIN_ROTATION = "Rotación principal",
	KEYBIND_ROLE_SPENDER = "Gastador",
	KEYBIND_ROLE_UTILITY = "Utilidad",
	KEYBIND_ROLE_DEFENSIVE = "Defensivo",
	KEYBIND_ROLE_MOBILITY = "Movilidad / mascota",
	KEYBIND_ROLE_COOLDOWN = "barra de enfriamiento",
	LAYOUT_PROTOTYPE_SUBTITLE = "Prototipo: vista previa completa del teclado estadounidense: las teclas de medianoche se iluminan; otros se volvieron grises. Coloca el cursor o haz clic. Las sugerencias en la pestaña Guía pueden saltar aquí y resaltar una clave. Es seguro quitarlo cuando se reemplaza.",
	LAYOUT_KEY_UNUSED_TOOLTIP = "|cff888888No se utiliza en el mapa de vinculación de Midnight Hunter.|r",
	LAYOUT_KEY_MODIFIER_TOOLTIP = "|cff888888Tecla modificadora: WoW maneja las combinaciones Shift/Ctrl/Alt por separado de este mapa de hechizos.|r",
	LAYOUT_KEY_NAV_TOOLTIP = "|cff888888Clúster de navegación/edición: no forma parte del mapa clave de Midnight.|r",
	LAYOUT_KEY_EMPTY_TOOLTIP = "|cffaaaaaaAún no hay función en esta clave en el mapa de especificaciones actual.|r",
	LAYOUT_KEY_G_OPTIONAL_TOOLTIP = "|cffaaaaaaLa ranura G existe en la cuadrícula, pero este equipo a menudo la deja vacía: enlace opcional.|r",
	LAYOUT_KEY_ROLE_TOOLTIP_FMT = "|cffffcc00%s|r",
	LAYOUT_KEY_BIND_LAYER_FMT = "|cffe0e070%s|r — %s",
	LAYOUT_KEY_MOVEMENT_TOOLTIP = "Mueve a tu personaje: W hacia adelante, S hacia atrás, A/D ametrallar, mouse para girar. WoW los usa de forma predeterminada: mantenlos libres para caminar.",
	LAYOUT_KEY_TAB_TOOLTIP = "La pestaña cambia de destino. WoW lo usa de forma predeterminada: mantén Tab libre para que puedas elegir rápidamente al enemigo adecuado en combate.",
	LAYOUT_KEY_PREFERRED_TOOLTIP = "Consejo de medianoche: mantén esta tecla libre para hechizos, macros o combinaciones Shift/Ctrl/Alt; la misma idea que las teclas F iluminadas en tus barras de acción.",
	LAYOUT_LEGEND = "|cff33ff61Green|r = moverse (W A S D).\\n|cffe0e070Gold|r = hechizos y atajos en este mapa.\\n|cff59d9ffTab|r = cambiar objetivos rápidamente.\\n|cff888888Grey|r = no en este mapa inicial.",
	LAYOUT_KEY_HIGHLIGHT_FROM_GUIDE = "|cffe0e070Abierto desde tu guía de nivelación: esta clave está en el mapa de Medianoche.|r",
	GUIDE_TIP_LAYOUT_KEY_BTN_FMT = "Mostrar la tecla |cffe0e070%s|r en la distribución del teclado",
	GUIDE_TIPS_KEY_HINT = "El equipo de Midnight usa claves fijas para los hechizos (en el mismo lugar siempre). Los botones dorados a la derecha abren la pestaña Diseño y muestran dónde se encuentra ese hechizo en tu teclado: desarrolla la memoria muscular en lugar de buscar barras en cada pelea.",
	MODULE_PLACEHOLDER = "Marcador de posición del módulo: el contenido de \\\"%s\\\" se montará aquí.",
	INFO_DRAWER_TOGGLE_SHOW = "Información",
	INFO_DRAWER_TOGGLE_HIDE = "Cerca",
	INFO_DRAWER_TITLE_FMT = "%s - Cómo utilizar",
	INFO_DRAWER_BODY_DELVES = "Centro de comando de Midnight Profundidades para tu personaje actual.\\n\\nExpande Great Vault para seguimiento de recompensas semanales, o Midnight Profundidades para obtener monedas de temporada (llaves de cofre restauradas, fragmentos semanales, Undercoins), el viaje/renombre de Delver y la lista completa de excavaciones con detección abundante en vivo desde los puntos de interés del mapa.\\n\\nNavegación: haz clic con el botón derecho en una fila para dirigirte a la entrada. |cffffcc00TomTom (recomendado)|r agrega la flecha del mapa y la cola de waypoints. |cff00ff00Travel Assistant|r (ventana emergente cuando estás lejos) muestra accesos directos al portal de Hearthstone y Hub y funciona |cffffff00sin|r TomTom.\\n\\nBuscar Bountiful más cercano requiere que TomTom esté instalado.",
	INFO_DRAWER_BODY_ACCOUNT = "Lista de personajes cruzados almacenada localmente por este complemento (variables guardadas en tu PC, no sincronización en la nube de Blizzard).\\n\\nCada fila enumera claves, fragmentos, undercoins, eco de profesiones y un resumen compacto de Great Vault con información sobre herramientas enriquecida; su carácter conectado se resalta y la clasificación favorece la utilidad.\\n\\nLas filas se actualizan al iniciar sesión y moneda/eventos semanales. Eliminar solo elimina los datos de la instantánea del complemento, nunca tu personaje real de WoW.",
	INFO_DRAWER_BODY_RARES = "Raros del mundo Midnight por zona (Eversong, Zul'Aman, Harandar, Voidstorm).\\n\\nElige una zona a la izquierda. Verde = hecho en este personaje; UP verde = viñeta en el spawn (probablemente activo); guion gris = no en tu mapa ahora.\\n\\nRare más cercano = un pin; Generar ruta = todos los raros abiertos en TomTom. El estado UP es orientativo — abre el mapa de zona o acércate si dudas.",
	RARES_TITLE = "Raros Midnight",
	RARES_SUBTITLE_FMT = "%d/%d hechos · %d visibles en el mapa (estrella plateada)",
	RARES_EMPTY_ZONE = "No hay lista de raros para esta zona.",
	RARES_ALL_DONE_WEEK = "Todos los raros hechos esta semana en este personaje — reset miércoles.",
	RARES_BTN_NEAREST = "Rare más cercano",
	RARES_BTN_ROUTE = "Generar ruta",
	RARES_NEAREST_ROUTE = "|cffffff78Midnight Helper:|r TomTom: rare más cercano — %s",
	RARES_NEAREST_NONE = "No quedan raros incompletos en esta zona.",
	RARES_NEAREST_NO_TRAVEL = "Travel Assistant no disponible (módulo Profundidades no cargado).",
	RARES_ROUTE_DONE_FMT = "%d/%d raros incompletos en TomTom. %s",
	RARES_ROUTE_ORDER_NEAR = "Orden: el más cercano primero, luego el siguiente en cada paso.",
	RARES_ROUTE_ORDER_LIST = "Orden: orden de lista (posición no disponible).",
	RARES_TAG_UP = "UP",
	RARES_TAG_DOWN = "—",
	RARES_TIP_DONE = "Hecho esta semana en este personaje (reset miércoles).",
	RARES_TIP_UP = "Probablemente activo (viñeta del mapa en el spawn).",
	RARES_TIP_DOWN = "No en el mapa ahora — puede aparecer más tarde.",
	RARES_TIP_VIGNETTE_NOTE = "Estado del mapa orientativo; abre el mapa de zona o acércate si no estás seguro.",
	INFO_DRAWER_BODY_SMC = "Referencia de Silvermoon City para Medianoche (mapa 2393). El mismo desplazamiento comienza con la lista de verificación Semanal/centro cuando se configuran los ID de las misiones, luego continúa en cuadrículas de pines categorizadas: Servicios esenciales, Viajes, Centros de misiones, Entrenadores profesionales, Reuniones y más.\\n\\nCada botón de ubicación establece el punto de ruta del usuario de Blizzard y, con TomTom instalado, lo refleja a través de la barra auxiliar (/way #2393…).\\n\\nEl progreso de la lista de verificación tiñe de verde los botones de los puntos de ruta relacionados; actualice los ID de misiones en los datos después de los parches principales si una fila parece incorrecta.",
	INFO_DRAWER_BODY_PROFESSIONS = "Realiza un seguimiento de los puntos de conocimiento (KP) de la profesión de medianoche para tu personaje actual, además de las líneas monetarias cuando el cliente las expone (Abundancia sin aleación, Moxie del artesano, Fragmentos de Dundun semanales).\\n\\nDebajo, dos columnas enumeran las misiones de adquisición de conocimientos y los libros de profesión por oficio; los iconos muestran si cada misión está completa. Haga clic en una fila para enviar solo ese marcador a TomTom (borra otros puntos de referencia; Travel Assistant maneja los saltos entre zonas cuando TomTom está cargado).\\n\\nLos botones inferiores colocan en cola por lotes pines incompletos: Generar tesoros o Generar libros (los más cercanos sin terminar primero cuando su posición en el mapa esté disponible).",
	INFO_DRAWER_BODY_GUIDE = "Referencias de nivelación de especificación por especificación diseñadas a partir de Icy Veins: prioridad de estadísticas, selección de equipo, consumibles filtrados según lo que tu nivel realmente puede usar, filas de consejos de hechizos opcionales y el Asesor de nivelación con pestañas de soporte para rotación, defensas y enfoque de talentos.\\n\\nCuando tu clase tiene un mapa de teclas de Medianoche (Hunter/Paladin por ahora), las sugerencias pueden mostrar un botón de llave dorada; haz clic en él para abrir la pestaña Diseño y resaltar esa tecla en el teclado. Eso vincula la lectura (qué presionar) con la ubicación (dónde en el teclado), para que aprenda haciendo.\\n\\nLa barra de búsqueda global entiende las palabras clave guía y puede saltar entre las pestañas de Midnight Helper; La vista previa te permite leer otra especialización sin volver a iniciar sesión mientras Mi personaje vuelve a tu especificación activa.\\n\\nLa visibilidad de la pestaña Guía sigue la Configuración: Automático (se oculta en el nivel 90+), Mostrar siempre u Ocultar siempre.",
	INFO_DRAWER_BODY_MACROS = "Pestaña Interrumpir: macro de patada de equipo (enfoque primero). Pestaña Utilidades: macros de especificaciones adicionales (hechizos de cursor en el suelo, curaciones al pasar el mouse y similares) del paquete del equipo. Elige una fila, lee el consejo, copia el texto.\\n\\nLos datos pueden cambiar después de los parches: informa al equipo de los hechizos que faltan.",
	INFO_DRAWER_BODY_ADDONS = "Centro para herramientas opcionales incluidas en Midnight Helper en lugar de descargas separadas.\\n\\nElija una subpestaña en la parte superior: hoy es Platynator: enlace Wago, importación de cadenas de perfil y la galería visual de MF Platynator.\\n\\nLos paneles de socios adicionales se registran aquí automáticamente cuando se envíen módulos futuros.",
	ABOUT_WINDOW_TITLE = "Acerca del ayudante de medianoche",
	ABOUT_VERSION_FMT = "Versión instalada: |cffffcc00%s|r",
	ABOUT_WINDOW_BODY = "Autores: Inchy & Gemma & Cursor\\n\\nTu compañero todo en uno de Midnight, organizado en cuatro salas — Me, Codex, Tools y Settings. Fija favoritos bajo la barra de búsqueda y escribe para saltar a cualquier sitio. Incluye Esta semana, Profundidades & Cámara, coaches de Profundidades y Rituales, el asesor de Encantamientos y Gemas, instantánea de cuenta, guías del Codex, profesiones y herramientas integradas — EN / NL / DE / FR / ES / PT / IT.",
	MAIN_TITLE_VERSION_FMT = "v%s",
	BROKER_TOOLTIP_VERSION_FMT = "Versión: %s",
	ABOUT_POPUP_TEXT = "Complemento: |cffffcc00Midnight Helper|r\\n\\nAutores: Inchy & Gemma & Cursor\\n\\nDescripción: Profundidades, Entrenador de profundidades, compartir en grupo, ventana emergente de elementos de profundidad, instantánea de cuenta, pines SMC, rastreador de KP de profesiones, guías de nivelación, herramientas incluidas: EN/NL/DE/FR/ES/PT/IT.",
	CHANGELOG_TITLE = "Registro de cambios del ayudante de medianoche",
	CHANGELOG_SUBTITLE = "Versión %s",
	CHANGELOG_VERSION_FMT = "Versión %s",
	CHANGELOG_CLOSE = "Cerca",
	CHANGELOG_CB_UNTIL_NEXT = "No volver a mostrar hasta la próxima versión.",
	CHANGELOG_CB_NEVER = "Ocultar permanentemente el registro de cambios",
	CHANGELOG_120_1 = "Se agregó un panel compacto de Asesor de nivelación con soportes y pestañas por nivel (Rotación / Defensivas / Enfoque en talento).",
	CHANGELOG_120_2 = "Sección de consumibles mejorada: solo muestra elementos utilizables en tu nivel actual y explica los próximos desbloqueos.",
	CHANGELOG_120_3 = "Se agregó administración de filas de instantáneas de cuenta: elimine caracteres obsoletos de forma segura (con confirmación) además de rayas de cebra.",
	CHANGELOG_120_4 = "Se mejoró la consistencia de la localización (EN/NL) y se agregó un glosario de estadísticas en la guía a través del nuevo ? Botón de estadísticas.",
	CHANGELOG_121_1 = "Ventana principal: los paneles interiores respetan el marco de diálogo dorado: los adornos de las esquinas permanecen visibles y el “canal vacío” inferior/derecho junto al control de cambio de tamaño desaparece.",
	CHANGELOG_121_2 = "Información y Acerca de usan nuevamente los botones estándar del panel de Blizzard (el mismo tratamiento que Buscar / Mi personaje) para una apariencia consistente en todos los clientes.",
	CHANGELOG_121_3 = "Sólo pulido menor; El comportamiento de profundidades, Vault, guías y localización no ha cambiado: actualización directa segura.",
	CHANGELOG_122_1 = "Pestaña Macros: macro de interrupción del equipo con un solo clic más macros de utilidad seleccionadas por especificación (cursor, mouseover, foco): copiar, pegar, reproducir.",
	CHANGELOG_122_2 = "Obtenga una vista previa de cualquier especificación sin volver a iniciar sesión: la búsqueda de guías actualiza consejos de nivelación, distribución del teclado y macros para esa clase/especificación de una sola vez.",
	CHANGELOG_122_3 = "La búsqueda de guías y los mensajes de chat siguen su elección de idioma (/mh lang en o nl).",
	CHANGELOG_122_4 = "Actualización del diseño de teclas a medianoche: interrupción en E, espacios de roles más claros, desbordamiento más inteligente (Alt, Shift, Ctrl).",
	CHANGELOG_122_5 = "Todavía se está cocinando: todo en Midnight Helper está sujeto a cambios y mejoras constantes; los parches seguirán llegando. ¡Bienvenidos comentarios!",
	CHANGELOG_130_1 = "Compartir consejos en grupo: envíe consejos de excavación al grupo, incursión o chat de instancia desde Entrenador de profundidades (resumen, jefe, secciones, copia). Prueba (/dice) cuando estés solo.",
	CHANGELOG_130_2 = "Ventana emergente de elementos de excavación: RAID-R Mini y Trovehunter's Bounty en excavaciones: panel automático + íconos de minimapa (solo en excavación; izquierda = ventana emergente, derecha = uso).",
	CHANGELOG_130_3 = "Entrenador de profundidades: Shift + rueda del mouse escala todo el panel (como Midnight Helper). Arrastre la esquina, la parte inferior o el borde derecho para cambiar el tamaño; Consejos de desplazamiento de la rueda.",
	CHANGELOG_130_4 = "Jefe destacado: vista previa confiable de la primera carga, corrección de texto de carga y zoom guardado por jefe.",
	CHANGELOG_130_5 = "Correcciones: compartir grupo solo cuando estés realmente agrupado; menos errores de chat; deletrea enlaces en consejos compartidos (EN/NL).",
	CHANGELOG_130_6 = "A partir de aquí, las versiones de parches pequeños pueden usar el nombre clave de Valeera en las notas; las funciones principales permanecen en 1.x.",
	CHANGELOG_126_1 = "Entrenador de profundidades: consejos flotantes para las 11 excavaciones de medianoche (descripción general, ruta, basura, jefe) en inglés y holandés.",
	CHANGELOG_126_2 = "Foco de jefe con vista previa en 3D; desplácese por el modelo para acercar o alejar (guardado por jefe).",
	CHANGELOG_126_3 = "Enlaces de hechizos azules en las puntas; vista previa desde la pestaña Profundidades o el entrenador /mh; exhibición automática en profundidades.",
	CHANGELOG_126_4 = "Ventana de entrenador arrastrable y de tamaño variable con minimización.",
	CHANGELOG_126_5 = "Correcciones de información sobre herramientas y cámara de Boss para comercio minorista.",
	CHANGELOG_125_1 = "Nueva pestaña Academia de roles: rutas de tanque y curación con listas de verificación de preparación, consejos de clasificación y una suave rampa desde las excavaciones hasta las mazmorras.",
	CHANGELOG_125_2 = "Enlaces rápidos desde Role Academy a macros, consumibles, guías de nivelación y profundidades.",
	CHANGELOG_125_3 = "Busque palabras clave (tanque, curación, academia, mentor) para abrir Role Academy.",
	CHANGELOG_124_1 = "Rutas de exploración y profesión: reserva de puntos de ruta del mapa de Blizzard cuando TomTom no está instalado (SuperTrack + ventana emergente de viaje sin cambios).",
	CHANGELOG_124_2 = "Instantánea de la cuenta: monedas semanales de la profesión en la información sobre herramientas (abundancia, fragmentos de Dundun, resumen de Moxie).",
	CHANGELOG_124_3 = "Excelentes recordatorios de restablecimiento de Vault: chat al iniciar sesión, líneas de información sobre herramientas del minimapa e ícono de minimapa pulsante (configurable).",
	CHANGELOG_124_4 = "Pulido de instantáneas de cuenta: ordenar/filtrar, nivel/ilvl, insignia obsoleta, cristales de maná no contaminados; Ruta de búsqueda de consumibles.",
	CHANGELOG_123_1 = "Se corrigió que el Asistente de viaje sugiriera erróneamente Hearthstone cuando ya estabas cerca de una excavación o dentro de una.",
	CHANGELOG_123_2 = "Se corrigió un error de Lua al enrutar a abundantes excavaciones (API de posición del mapa).",
	CHANGELOG_123_3 = "Pestaña de la barra lateral de consumibles: listas respaldadas por Wowhead por especificación, con vista previa de búsqueda de guía.",
	CHANGELOG_123_4 = "Guía TomTom más clara (EN/NL): opcional para las flechas del mapa; Travel Assistant funciona sin TomTom.",
